use std::collections::HashMap;
use std::fmt;

/// Errors returned when parsing configuration text.
#[derive(Debug)]
#[non_exhaustive]
pub enum ConfigError {
    /// A line did not contain a `=` separator.
    BadLine {
        /// 1-based line number in the input.
        line: usize,
        /// The offending line, as it appeared.
        content: String,
    },
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::BadLine { line, content } => {
                write!(f, "line {line}: expected `key=value`, got `{content:?}`")
            }
        }
    }
}

impl std::error::Error for ConfigError {}

fn parse_line(line: &str) -> Result<(String, String), ()> {
    let (key, value) = line.split_once('=').ok_or(())?;
    Ok((key.trim().to_string(), value.trim().to_string()))
}

pub fn load(text: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut map = HashMap::new();
    for (n, line) in text.lines().enumerate() {
        let (key, value) =
            parse_line(line).map_err(|_| ConfigError::BadLine { line: n + 1, content: line.to_string() })?;
        map.insert(key, value);
    }
    Ok(map)
}
```

