```rust
//! Loading of simple `key=value` configuration files.

use std::collections::HashMap;
use std::fmt;

/// An error from parsing configuration text.
#[derive(Debug)]
#[non_exhaustive]
pub enum ConfigError {
    /// A line did not contain a `=` separator.
    BadLine {
        /// 1-based position of the offending line.
        line: usize,
        /// The line as it appeared in the input.
        content: String,
    },
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::BadLine { line, content } => {
                write!(f, "line {line}: expected `key=value`, got `{content}`")
            }
        }
    }
}

impl std::error::Error for ConfigError {}

/// Splits one `key=value` line into a trimmed key and value.
fn parse_line(line: &str) -> Option<(String, String)> {
    let (key, value) = line.split_once('=')?;
    Some((key.trim().to_string(), value.trim().to_string()))
}

/// Parses a whole config file into a map.
///
/// Duplicate keys: the last occurrence wins.
///
/// # Errors
/// Returns [`ConfigError::BadLine`] for any line without a `=` separator.
pub fn load(text: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut map = HashMap::new();
    for (n, line) in text.lines().enumerate() {
        let (key, value) = parse_line(line)
            .ok_or_else(|| ConfigError::BadLine { line: n + 1, content: line.to_string() })?;
        map.insert(key, value);
    }
    Ok(map)
}

